/**
 * diarization-long-proof.js — S-D06 (#1908) long-recording proof harness.
 *
 * Runs synthetic fixtures (generated by
 * scripts/generate-diarization-fixtures.py — local flite TTS voices,
 * ground truth by construction) through the FULL worker path:
 * diarizationJobs.enqueue/claim → workers/diarization processJob
 * (claim-time + write-time consent gates) → lib/diarizationEngine
 * (ffmpeg decode, pipe-to-memory) → workers/diarization/engine-child.mjs
 * (pinned @desert-ant-labs/who@4.2.1) → diarization_runs row, read back.
 *
 * The ONLY injected seam is fetchAudio returning the fixture buffer —
 * the S-D05 integration precedent (the fixture has no storage object;
 * the storage fetch is the transcribe handler's already-proven path).
 *
 * Measurements are RAW: end-to-end latency is the wall time of
 * processJob (gates + decode + engine + run-row insert); peak RSS is
 * the peak, sampled every 250 ms, of this process's whole tree
 * (supervisor + ffmpeg + engine child) from `ps`. Nothing is
 * extrapolated and nothing is rounded into a pass.
 *
 * AC-1 criterion (stated up front): a ground-truth voice "corresponds
 * to exactly one speaker number" in a window when exactly one engine
 * speaker overlaps that voice's speech in the window by >= 0.5 s.
 * Sub-0.5 s overlaps (boundary slivers) are still reported raw in
 * perVoice.overlaps — they are not hidden, they just do not count as
 * a second speaker for the voice.
 *
 * Hardened in #1929 (M1): a window passes only when EVERY expected
 * voice is present in it with exactly one engine speaker AND distinct
 * voices map to distinct engine speakers. Before that, a fully merged
 * join ({interviewer: 0, candidate: 0} in both windows) returned
 * joinPass: true, and a window observing only one of the two voices
 * passed — the evaluator never compared against the expected voice set
 * and never checked distinctness.
 *
 * Usage:
 *   DATABASE_URL='postgresql://postgres@127.0.0.1:55433/sd06_e2e' \
 *   DIARIZATION_WEIGHTS_DIR=$HOME/.cache/rekrut-diarization/weights \
 *     node scripts/diarization-long-proof.js \
 *       --fixtures-dir <dir> --results <results.json> [--only 60min]
 *
 * Exit code: 0 only if every run fixture completed AND passed its
 * join + phantom checks; 1 otherwise (results are written either way).
 */
const fs = require('node:fs');
const path = require('node:path');
const { execFileSync } = require('node:child_process');

const MIN_OVERLAP_S = 0.5;

function overlapsInWindow(gtTurns, engineTurns, startS, endS) {
	const perVoice = {};
	for (const g of gtTurns) {
		const gStart = Math.max(g.start_s, startS);
		const gEnd = Math.min(g.end_s, endS);
		if (gEnd <= gStart) continue;
		if (!perVoice[g.speaker]) perVoice[g.speaker] = {};
		for (const e of engineTurns) {
			const oStart = Math.max(gStart, e.start_s);
			const oEnd = Math.min(gEnd, e.end_s);
			if (oEnd > oStart) {
				perVoice[g.speaker][e.speaker] = (perVoice[g.speaker][e.speaker] || 0) + (oEnd - oStart);
			}
		}
	}
	return perVoice;
}

function evaluateWindow(gtTurns, engineTurns, startS, endS, expectedVoices = null) {
	const raw = overlapsInWindow(gtTurns, engineTurns, startS, endS);
	// The expected voice set (#1929 M1): an explicit parameter wins;
	// otherwise derive it from the FULL ground truth handed in, so a
	// voice that never speaks inside this window is still expected —
	// and its absence fails the window instead of passing silently.
	const expected = expectedVoices ?? [...new Set(gtTurns.map((t) => t.speaker))];
	const perVoice = {};
	const mapping = {};
	let pass = expected.length > 0;
	for (const [voice, overlaps] of Object.entries(raw)) {
		const engineSpeakers = Object.entries(overlaps)
			.filter(([, s]) => s >= MIN_OVERLAP_S)
			.map(([sp]) => Number(sp))
			.sort((a, b) => a - b);
		perVoice[voice] = {
			engineSpeakers,
			overlaps_s: Object.fromEntries(
				Object.entries(overlaps).map(([sp, s]) => [sp, +s.toFixed(3)]),
			),
		};
		mapping[voice] = engineSpeakers.length === 1 ? engineSpeakers[0] : null;
		if (engineSpeakers.length !== 1) pass = false;
	}
	// Every expected voice must be present (mapping has an entry for it).
	for (const voice of expected) {
		if (!(voice in mapping)) pass = false;
	}
	// Distinctness (#1929 M1): distinct voices must map to distinct
	// engine speakers — a merged join is a failed join.
	const mappedSpeakers = Object.values(mapping).filter((s) => s !== null);
	if (new Set(mappedSpeakers).size !== mappedSpeakers.length) pass = false;
	return { window_s: [startS, endS], pass, mapping, perVoice };
}

// Canonical window definition (#1929 m9): "Minute N" = the 60-second
// window starting at timestamp N:00 — [N×60, (N+1)×60) seconds.
// Minute 2 = [120,180], minute 28 = [1680,1740], minute 40 = [2400,2460].
function minute2Window(durationS) {
	return durationS >= 180 ? [120, 180] : null;
}

// For a fixture shorter than 180 s, minute 2 does not exist and must
// not be silently substituted. The distinctly named early window is
// evaluated instead and recorded under its own key — never as
// unqualified minute2.
const EARLY_WINDOW_S = [60, 120];

function evaluateFixture(gt, run) {
	const duration = gt.duration_s;
	const m2 = minute2Window(duration);
	const minute2 = m2
		? evaluateWindow(gt.turns, run.turns, m2[0], m2[1], gt.speakers)
		: null;
	const earlyWindow = m2
		? null
		: evaluateWindow(gt.turns, run.turns, EARLY_WINDOW_S[0], EARLY_WINDOW_S[1], gt.speakers);
	// The window the join is checked against: canonical minute 2 when
	// it exists, otherwise the early window under its own name.
	const primary = minute2 ?? earlyWindow;
	const finalMinute = evaluateWindow(gt.turns, run.turns, duration - 60, duration, gt.speakers);
	const distinctEngineSpeakers = [...new Set(run.turns.map((t) => t.speaker))].sort(
		(a, b) => a - b,
	);
	const mappingsConsistent = Object.keys(primary.mapping).every(
		(v) => primary.mapping[v] !== null && primary.mapping[v] === finalMinute.mapping[v],
	);
	// Distinctness at the fixture level (#1929 M1): each window's mapping
	// must be injective — distinct voices, distinct engine speakers.
	const injective = (mapping) => {
		const speakers = Object.values(mapping).filter((s) => s !== null);
		return new Set(speakers).size === speakers.length;
	};
	return {
		joinPass: Boolean(
			primary.pass &&
				finalMinute.pass &&
				mappingsConsistent &&
				injective(primary.mapping) &&
				injective(finalMinute.mapping),
		),
		phantomPass:
			run.speakerCount === gt.speakers.length &&
			distinctEngineSpeakers.length === gt.speakers.length,
		speakerCount: run.speakerCount,
		distinctEngineSpeakers,
		mappingMinute2: minute2 ? minute2.mapping : null,
		mappingEarlyWindow: earlyWindow ? earlyWindow.mapping : null,
		mappingFinalMinute: finalMinute.mapping,
		minute2,
		earlyWindow,
		finalMinute,
	};
}

/** Peak-RSS sampler over this process's tree (supervisor + children). */
function startRssSampler(intervalMs = 250) {
	let peakTreeKb = 0;
	let peakSelfKb = 0;
	const sample = () => {
		try {
			const out = execFileSync('ps', ['-eo', 'pid=,ppid=,rss='], { encoding: 'utf8' });
			const procs = new Map();
			for (const line of out.trim().split('\n')) {
				const [pid, ppid, rss] = line.trim().split(/\s+/).map(Number);
				if (Number.isFinite(pid)) procs.set(pid, { ppid, rss: rss || 0 });
			}
			const self = procs.get(process.pid);
			if (self) peakSelfKb = Math.max(peakSelfKb, self.rss);
			let treeKb = 0;
			const stack = [process.pid];
			const seen = new Set();
			while (stack.length) {
				const pid = stack.pop();
				if (seen.has(pid)) continue;
				seen.add(pid);
				const p = procs.get(pid);
				if (p) treeKb += p.rss;
				for (const [cpid, cp] of procs) if (cp.ppid === pid) stack.push(cpid);
			}
			peakTreeKb = Math.max(peakTreeKb, treeKb);
		} catch {
			/* a missed sample never fails the measurement */
		}
	};
	sample();
	const timer = setInterval(sample, intervalMs);
	return {
		stop() {
			clearInterval(timer);
			sample();
			return {
				peak_tree_rss_mb: +(peakTreeKb / 1024).toFixed(1),
				peak_self_rss_mb: +(peakSelfKb / 1024).toFixed(1),
			};
		},
	};
}

const FIXTURES = [
	{ name: '2min', base: 'diarization-2min' },
	{ name: '30min', base: 'diarization-30min' },
	{ name: '60min', base: 'diarization-60min' },
];

async function main() {
	const args = process.argv.slice(2);
	const arg = (k) => {
		const i = args.indexOf(k);
		return i >= 0 ? args[i + 1] : null;
	};
	const fixturesDir = arg('--fixtures-dir');
	const resultsPath = arg('--results');
	const only = arg('--only');
	if (!fixturesDir || !resultsPath) {
		console.error('usage: --fixtures-dir <dir> --results <file> [--only 2min|30min|60min]');
		process.exit(2);
	}
	if (!process.env.DATABASE_URL) {
		console.error('DATABASE_URL must point at the fresh-migrated proof DB');
		process.exit(2);
	}

	const { Pool } = require('pg');
	const consentService = require('../lib/consentService');
	const diarizationJobs = require('../lib/diarizationJobs');
	const worker = require('../workers/diarization/index');
	const pool = new Pool({ connectionString: process.env.DATABASE_URL });

	const results = {
		story: 'S-D06 (#1908)',
		started_at: new Date().toISOString(),
		vm: {
			cpus: require('node:os').cpus().length,
			mem_total_mb: Math.round(require('node:os').totalmem() / 1048576),
		},
		weights_cache: fs.existsSync(path.join(process.env.DIARIZATION_WEIGHTS_DIR || '', '.dal-meta'))
			? 'warm (pre-provisioned cache)'
			: 'cold/unknown',
		fixtures: [],
	};
	const writeResults = () => fs.writeFileSync(resultsPath, JSON.stringify(results, null, 2));

	let allPass = true;
	for (const fx of FIXTURES) {
		if (only && fx.name !== only) continue;
		const wavPath = path.join(fixturesDir, `${fx.base}.wav`);
		const gtPath = path.join(fixturesDir, `${fx.base}.ground-truth.json`);
		const gt = JSON.parse(fs.readFileSync(gtPath, 'utf8'));
		const wav = fs.readFileSync(wavPath);
		const tag = `sd06-${fx.name}`;
		console.log(
			`[sd06] ${fx.name}: seeding + running full worker path (${gt.duration_s}s fixture, ${(wav.length / 1048576).toFixed(1)} MB wav)`,
		);

		const cand = await pool.query(`INSERT INTO users (email) VALUES ($1) RETURNING id`, [
			`${tag}-candidate@example.test`,
		]);
		const candidateId = cand.rows[0].id;
		await pool.query(`INSERT INTO users (email) VALUES ($1)`, [`${tag}-recruiter@example.test`]);
		const sess = await pool.query(
			`INSERT INTO interview_sessions (candidate_id, type, config, conversation, current_question_index)
			 VALUES ($1, 'human', '{}'::jsonb, '[]'::jsonb, 0) RETURNING id`,
			[candidateId],
		);
		const sessionId = sess.rows[0].id;
		const rec = await pool.query(
			`INSERT INTO interview_recordings (interview_event_id, interview_session_id, status, retention_expires_at)
			 VALUES (NULL, $1, 'completed', NOW() + INTERVAL '90 days') RETURNING id`,
			[sessionId],
		);
		const recordingId = rec.rows[0].id;
		await pool.query(
			`INSERT INTO interview_transcripts (recording_id, speaker_identity, text, start_time_ms, end_time_ms)
			 VALUES ($1, 'unknown', 'synthetic fixture', 0, $2)`,
			[recordingId, Math.round(gt.duration_s * 1000)],
		);
		await consentService.recordConsent({
			sessionId,
			candidateId,
			type: 'biometric',
			accepted: true,
			locale: 'en',
		});

		await diarizationJobs.enqueue(recordingId);
		const job = await diarizationJobs.claim(`sd06-proof-${fx.name}`);

		const sampler = startRssSampler();
		const t0 = Date.now();
		let outcome;
		let processError = null;
		try {
			outcome = await worker.processJob(job, { fetchAudio: async () => wav });
		} catch (err) {
			processError = String(err?.message || err);
		}
		const latencyS = +((Date.now() - t0) / 1000).toFixed(3);
		const rss = sampler.stop();

		const entry = {
			fixture: fx.name,
			duration_s: gt.duration_s,
			wav_bytes: wav.length,
			outcome: outcome ? outcome.outcome : 'threw',
			process_error: processError,
			latency_s: latencyS,
			...rss,
		};

		if (outcome && outcome.outcome === 'complete') {
			const { rows } = await pool.query(
				`SELECT engine_package, sdk_version, model_version, speaker_count, turns, coverage_end_ms
				 FROM diarization_runs WHERE recording_id = $1 AND job_id = $2`,
				[recordingId, job.id],
			);
			const run = rows[0];
			entry.engine = {
				package: run.engine_package,
				sdk_version: run.sdk_version,
				model_version: run.model_version,
			};
			entry.turns_count = run.turns.length;
			entry.turns = run.turns;
			entry.per_speaker_s = {};
			for (const t of run.turns) {
				entry.per_speaker_s[t.speaker] = +(
					(entry.per_speaker_s[t.speaker] || 0) +
					(t.end_s - t.start_s)
				).toFixed(3);
			}
			entry.coverage_end_ms = Number(run.coverage_end_ms);
			entry.evaluation = evaluateFixture(gt, { speakerCount: run.speaker_count, turns: run.turns });
			if (!entry.evaluation.joinPass || !entry.evaluation.phantomPass) allPass = false;
		} else {
			allPass = false;
			const { rows } = await pool.query(
				`SELECT status, error_class, error_message FROM diarization_jobs WHERE id = $1`,
				[job.id],
			);
			entry.job_state = rows[0] || null;
		}
		console.log(
			`[sd06] ${fx.name}: outcome=${entry.outcome} latency_s=${latencyS} peak_tree_rss_mb=${rss.peak_tree_rss_mb} join=${entry.evaluation?.joinPass} phantom=${entry.evaluation?.phantomPass}`,
		);
		results.fixtures.push(entry);
		writeResults();

		await pool
			.query(`DELETE FROM interview_recordings WHERE id = $1`, [recordingId])
			.catch(() => {});
		await pool.query(`DELETE FROM interview_sessions WHERE id = $1`, [sessionId]).catch(() => {});
		await pool
			.query(`DELETE FROM users WHERE email LIKE $1`, [`${tag}-%@example.test`])
			.catch(() => {});
	}

	results.finished_at = new Date().toISOString();
	writeResults();
	await pool.end();
	const db = require('../lib/db');
	if (db.end) await db.end().catch(() => {});
	console.log(`[sd06] done. allPass=${allPass} results=${resultsPath}`);
	process.exit(allPass ? 0 : 1);
}

if (require.main === module) {
	main().catch((err) => {
		console.error('[sd06] harness failed:', err);
		process.exit(2);
	});
}

module.exports = {
	evaluateWindow,
	evaluateFixture,
	overlapsInWindow,
	MIN_OVERLAP_S,
	minute2Window,
	EARLY_WINDOW_S,
};
